<script setup lang="ts">
import {computed,inject,onMounted,ref} from 'vue';
import {RouterLink} from 'vue-router';
import {Building2,Search,Pencil,GitMerge,ArrowLeft,Save} from '@lucide/vue';
import {api} from '../../lib/api';
import type {CompanySummary,CompanyType} from '../../../shared/types';
import {categoryLabel,companyTypes} from '../../../shared/catalog';
import {adminSessionKey,messageOf} from './helpers';
import AdminState from './AdminState.vue';
import AdminModal from './AdminModal.vue';
const session=inject(adminSessionKey)!;
const companies=ref<CompanySummary[]>([]),loading=ref(true),error=ref(''),success=ref(''),query=ref(''),filter=ref(''),editing=ref<CompanySummary|null>(null),merging=ref<CompanySummary|null>(null),name=ref(''),companyType=ref<CompanyType>('airline'),target=ref(''),busy=ref(false),modalError=ref(''),confirmed=ref(false);
const filtered=computed(()=>companies.value.filter(c=>(!query.value||(c.name+' '+c.normalizedName).toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))&&(!filter.value||c.companyType===filter.value)));
async function load(){const result=await api<{companies:CompanySummary[]}>('/api/admin/companies');companies.value=result.companies;}
function edit(company:CompanySummary){editing.value=company;name.value=company.name;companyType.value=company.companyType;modalError.value='';}
function merge(company:CompanySummary){merging.value=company;target.value='';confirmed.value=false;modalError.value='';}
function close(){if(!busy.value){editing.value=null;merging.value=null;}}
async function save(){busy.value=true;modalError.value='';const wasEditing=!!editing.value;try{await api('/api/admin/companies',{method:'PATCH',body:JSON.stringify(editing.value?{action:'update',id:editing.value.id,name:name.value.trim(),companyType:companyType.value}:{action:'merge',sourceId:merging.value?.id,targetId:target.value})});await load();editing.value=null;merging.value=null;success.value=wasEditing?'פרטי החברה עודכנו.':'רשומות החברה אוחדו. המקור נשמר בתיעוד המערכת.';}catch(e){modalError.value=messageOf(e);}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>{error.value=messageOf(e);}).finally(()=>{loading.value=false;}));
</script>
<template><div class="admin-page-heading"><div><span class="admin-eyebrow">מאגר חברות וגופים</span><h1>חברות וספקים</h1><p>רשומות חברות אחידות לחיבור בין דיווחים ולאיתור דפוסים.</p></div><span class="admin-total-label"><Building2 :size="18"/>{{companies.length}} חברות</span></div><div v-if="error" class="admin-error" role="alert">{{error}}</div><div v-if="success" class="admin-success" role="status">{{success}}</div><div class="admin-info">הופעה במאגר מבוססת על דיווחי צרכנים ואינה מעידה על הפרת חוק.</div><section class="admin-panel"><div class="admin-company-filters"><label class="admin-search"><Search :size="18"/><input v-model="query" placeholder="חיפוש חברה או ספק…" aria-label="חיפוש חברות"/></label><select v-model="filter" class="select" aria-label="סוג ספק"><option value="">כל סוגי הספקים</option><option v-for="type in companyTypes" :key="type.id" :value="type.id">{{type.label}}</option></select><span>{{filtered.length}} תוצאות</span></div><AdminState v-if="loading" loading/><div v-else-if="filtered.length" class="table-wrap"><table class="data-table admin-companies-table"><thead><tr><th>שם החברה</th><th>סוג ספק</th><th>דיווחים</th><th>סוגי אירועים</th><th>פעולות</th></tr></thead><tbody><tr v-for="company in filtered" :key="company.id"><td><span class="admin-company-name"><span class="admin-company-initial">{{company.name.charAt(0)}}</span><strong>{{company.name}}</strong></span></td><td>{{companyTypes.find(t=>t.id===company.companyType)?.label}}</td><td><span class="admin-count">{{company.reportCount}}</span></td><td><div class="admin-category-tags"><span v-for="category in company.byCategory" :key="category.category">{{categoryLabel(category.category)}} <b>{{category.count}}</b></span></div></td><td><div class="admin-row-actions"><RouterLink :to="{path:'/admin/reports',query:{company:company.name}}" class="admin-text-link">דיווחים<ArrowLeft :size="14"/></RouterLink><template v-if="session.role==='administrator'"><button class="admin-icon-button" :aria-label="'עריכת '+company.name" @click="edit(company)"><Pencil :size="16"/></button><button class="admin-icon-button" :aria-label="'איחוד '+company.name" :disabled="companies.length<2" @click="merge(company)"><GitMerge :size="17"/></button></template></div></td></tr></tbody></table></div><AdminState v-else title="לא נמצאו חברות" description="נסו שם אחר או בחרו סוג ספק שונה."/></section>
<AdminModal v-if="editing||merging" :title="editing?'עריכת חברה':'איחוד רשומות חברה'" :busy="busy" @close="close"><form @submit.prevent="save"><div class="admin-modal-body"><div v-if="modalError" class="admin-error" role="alert">{{modalError}}</div><template v-if="editing"><label class="field"><span class="field-label">שם החברה</span><input v-model="name" class="input" required minlength="2" maxlength="200"/></label><label class="field"><span class="field-label">סוג ספק</span><select v-model="companyType" class="select"><option v-for="type in companyTypes" :key="type.id" :value="type.id">{{type.label}}</option></select></label></template><template v-else><div class="admin-merge-source"><Building2 :size="24"/><span>הרשומה שתאוחד<strong>{{merging?.name}}</strong><small>{{merging?.reportCount}} דיווחים</small></span></div><label class="field"><span class="field-label">החברה שאליה יועבר השיוך</span><select v-model="target" class="select" required><option value="">בחירת חברה</option><option v-for="company in companies.filter(c=>c.id!==merging?.id)" :key="company.id" :value="company.id">{{company.name}} ({{company.reportCount}} דיווחים)</option></select></label><div v-if="target" class="admin-info">הדיווחים יקושרו לרשומה ״{{companies.find(c=>c.id===target)?.name}}״. פרטי המקור ותיעוד האיחוד נשמרים.</div><label class="admin-checkbox"><input v-model="confirmed" type="checkbox" required/>בדקתי שמדובר באותה חברה או באותו ספק.</label></template></div><div class="admin-modal-footer"><button class="btn btn-secondary" type="button" :disabled="busy" @click="close">ביטול</button><button class="btn btn-primary" :disabled="busy||(!editing&&(!target||!confirmed))"><Save :size="16"/>{{editing?'שמירת הפרטים':'אישור ואיחוד'}}</button></div></form></AdminModal></template>
